      context: "Ví dụ cổ điển: chữ 来 (Lai) nguyên nghĩa là cây lúa mạch, mượn âm dùng làm động từ 'đến'; 北 (Bắc) vẽ hai người quay lưng vào nhau ('bội/trái'), mượn chỉ phương Bắc.",
      examples: [
        { zh: "“来”本指小麦，后来假借为“往来”之“来”。", pinyin: "“Lái” běn zhǐ xiǎomài, hòulái jiǎjiè wéi “wǎnglái” zhī “lái”.", en: "'Lai' originally meant wheat and was phonetically loaned for the verb 'to come'.", vi: "Chữ 'Lai' vốn chỉ lúa mạch, về sau được giả tá để mang nghĩa 'đi lại, đến'." },
        { zh: "假借法大幅减少了无限造字的负担。", pinyin: "Jiǎjièfǎ dàfú jiǎnshǎo le wúxiàn zàozì de fùdān.", en: "Phonetic loaning vastly reduced the burden of endlessly coining new graphs.", vi: "Phép Giả tá giảm thiểu đáng kể gánh nặng phải đặt ra vô hạn chữ mới." },
        { zh: "阅读古籍时，必须善于识别通假字与假借现象。", pinyin: "Yuèdú gǔjí shí, bìxū shànyú shíbié tōngjiǎzì yǔ jiǎjiè xiànxiàng.", en: "Reading classical texts requires skill in recognizing phonetic loans and interchangeable graphs.", vi: "Khi đọc cổ thư nhất thiết phải thạo nhận diện thông giả tự và hiện tượng giả tá." }
      ]
