        { zh: "转注揭示了古汉语方言语音分化的历史痕迹。", pinyin: "Zhuǎnzhù jiēshì le gǔ Hànyǔ fāngyán yǔyīn fēnhuà de lìshǐ hénjì.", en: "Zhuanzhu reveals historical traces of dialectal phonetic divergence in Old Chinese.", vi: "Chuyển chú hé lộ dấu tích lịch sử của sự phân hóa phương ngôn trong Hán ngữ cổ." },
        { zh: "现代文字学者将转注视作同源词的互训现象。", pinyin: "Xiàndài wénzì xuézhě jiāng zhuǎnzhù shìzuò tóngyuáncí de hùxùn xiànxiàng.", en: "Modern paleographers treat zhuanzhu as mutual glossing of cognate words.", vi: "Học giả văn tự hiện đại xem Chuyển chú như hiện tượng hỗ huấn giữa các từ đồng nguyên." }
