        { zh: "本词典的零拼音卡片即围绕部首拆解进行设计。", pinyin: "Běn cídiǎn de líng-pīnyīn kǎpiàn jí wéirào bùshǒu chāijiě jìnxíng shèjì.", en: "This dictionary's zero-pinyin flashcards are structured around radical decomposition.", vi: "Bộ thẻ ghi nhớ không phiên âm của từ điển này được thiết kế xoay quanh phân rã bộ thủ." }
