      traditional: "民貴君輕",
      pinyin: "mín guì jūn qīng",
      hanViet: "DÂN QUÝ QUÂN KHINH",
      level: "Advanced / Academic Chinese",
      topicTag: "Nho học Mạnh Tử",
      pos: "phr.",
      liushuType: "象形 · 会意",
