      context: "Thời cận đại còn được dùng để dịch thuật ngữ 'Khoa học tự nhiên / Vật lý' trước khi từ 'Khoa học' (科学) phổ biến.",
      examples: [
        { zh: "《大学》将“格物致知”列为修身治国之起点。", pinyin: "《Dàxué》 jiāng “géwù zhìzhī” lièwéi xiūshēn zhìguó zhī qǐdiǎn.", en: "The Great Learning places investigating things at the start of personal and civic cultivation.", vi: "Sách Đại Học đặt 'Cách vật trí tri' làm điểm khởi đầu của lộ trình tu thân trị quốc." },
        { zh: "朱熹主张“即物穷理”，逐一考究事物规律。", pinyin: "Zhū Xī zhǔzhāng “jí wù qióng lǐ”, zhúyī kǎojiū shìwù guīlǜ.", en: "Zhu Xi advocated studying concrete phenomena one by one to exhaust their principles.", vi: "Chu Hy chủ trương 'tức vật cùng lý', khảo cứu từng sự vật để thấu suốt đạo lý." },
        { zh: "清末曾长期以“格致”指代自然科学与物理实验。", pinyin: "Qīngmò céng chángqī yǐ “gézhì” zhǐdài zìrán kēxué yǔ wùlǐ shíyàn.", en: "In late Qing, 'gezhi' long served as the term for natural science and experimental physics.", vi: "Cuối đời Thanh từng dùng từ 'Cách trí' để chỉ khoa học tự nhiên và vật lý thực nghiệm." }
      ]
