      mnemonic: "Dòng nước lớn (氵+告) nuôi dưỡng luồng khí phách thẳng ngay bất khuất (气) tràn đầy giữa trời đất.",
      context: "Linh hồn nhân cách kẻ sĩ Đông Á: 'Phú quý bất năng dâm, bần tiện bất năng di, uy vũ bất năng khuất'.",
      examples: [
        { zh: "孟子自言“我善养吾浩然之气”，此气至大至刚，集义而生。", pinyin: "Mèngzǐ zì yán “Wǒ shàn yǎng wú hàorán zhī qì”, cǐ qì zhì dà zhì gāng, jí yì ér shēng.", en: "Mencius stated he nurtured his flood-like qi—vast, unyielding, and born of accumulated righteousness.", vi: "Mạnh Tử từng nói 'Ta khéo nuôi cái Hạo nhiên chi khí của ta', khí ấy chí đại chí cương, do tích tụ điều nghĩa mà sinh." },
        { zh: "文天祥《正气歌》正是对浩然之气的千古传颂。", pinyin: "Wén Tiānxiáng 《Zhèngqì Gē》 zhèng shì duì hàorán zhī qì de qiāngǔ chuánsòng.", en: "Wen Tianxiang's Song of Righteousness immortally extols this flood-like moral spirit.", vi: "Bài Chính khí ca của Văn Thiên Tường chính là khúc tráng ca ngợi ca Hạo nhiên chi khí." },
        { zh: "文章风骨往往源自作者胸中之浩然气韵。", pinyin: "Wénzhāng fēnggǔ wǎngwǎng yuánzì zuòzhě xiōngzhōng zhī hàorán qìyùn.", en: "Literary backbone often flows from an author's inner moral vitality.", vi: "Cốt cách bài văn thường bắt nguồn từ luồng hạo nhiên khí trong tâm hồn người viết." }
      ]
