      context: "Đối thoại kinh điển suốt hai nghìn năm giữa Mạnh Tử ('Nhân chi sơ, tính bản thiện') và Tuân Tử ('Nhân tính bản ác, kỳ thiện giả ngụy dã').",
      examples: [
        { zh: "《三字经》开篇“人之初，性本善”正源自孟子的性善论。", pinyin: "《Sānzìjīng》 kāipiān “Rén zhī chū, xìng běn shàn” zhèng yuánzì Mèngzǐ de xìngshànlùn.", en: "The Three Character Classic's famous opening line derives directly from Mencius's innate goodness doctrine.", vi: "Câu mở đầu Tam Tự Kinh 'Nhân chi sơ, tính bản thiện' bắt nguồn thẳng từ Tính thiện luận của Mạnh Tử." },
        { zh: "孟子以“孺子将入于井”的恻隐之心来证成性善。", pinyin: "Mèngzǐ yǐ “rúzǐ jiāng rù yú jǐng” de cèyǐn zhī xīn lái zhèngchéng xìngshàn.", en: "Mencius proved innate goodness via spontaneous alarm when seeing a child about to fall into a well.", vi: "Mạnh Tử lấy lòng trắc ẩn khi thấy đứa trẻ sắp ngã xuống giếng để chứng minh bản tính thiện." },
        { zh: "相比之下，荀子更强调通过礼法教化来制约人性偏私。", pinyin: "Xiāngbǐ zhīxià, Xúnzǐ gèng qiángdiào tōngguò lǐfǎ jiàohuà lái zhìyuē rénxìng piānsī.", en: "In contrast, Xunzi stressed curbing selfish impulses through ritual and legal cultivation.", vi: "Ngược lại, Tuân Tử nhấn mạnh hơn việc dùng lễ pháp giáo hóa để uốn nắn phần thiên tư của nhân tính." }
      ]
