      mnemonic: "Người giữ trọng trách cắt đặt nội trị (宰) và sáng suốt phụ tá bên cạnh quân vương (相).",
      context: "Lịch sử quyền lực quân chủ Trung Hoa là cuộc giằng co kinh điển giữa Hoàng quyền (Vua) và Tướng quyền (Tể tướng), kết thúc khi Chu Nguyên Chương phế bỏ Thừa tướng năm 1380.",
      examples: [
        { zh: "历史上名臣如萧何、诸葛亮、房玄龄、张居正皆行宰相之实。", pinyin: "Lìshǐ shàng míngchén rú Xiāo Hé, Zhūgě Liàng, Fáng Xuánlíng, Zhāng Jūzhèng jiē xíng zǎixiàng zhī shí.", en: "Historic statesmen like Xiao He, Zhuge Liang, and Zhang Juzheng exercised chancellor leadership.", vi: "Các danh thần như Tiêu Hà, Gia Cát Lượng, Phòng Huyền Linh, Trương Cư Chính đều đảm đương thực quyền Tể tướng." },
        { zh: "范仲淹名言“不为良相，便为良医”流传千古。", pinyin: "Fàn Zhòngyān míngyán “Bù wéi liángxiàng, biàn wéi liángyī” liúchuán qiāngǔ.", en: "Fan Zhongyan's maxim 'If not a good chancellor, then a good physician' remains immortal.", vi: "Danh ngôn của Phạm Trọng Yêm 'Bất vi lương tướng, tiện vi lương y' lưu truyền ngàn đời." },
        { zh: "皇权与相权的消长贯穿了中国两千年帝制史。", pinyin: "Huángquán yǔ xiàngquán de xiāozhǎng guànchuān le Zhōngguó liǎngqiān nián dìzhìshǐ.", en: "The ebb and flow between imperial and ministerial power ran through two millennia of monarchy.", vi: "Sự thăng trầm giữa hoàng quyền và tướng quyền xuyên suốt hai nghìn năm lịch sử quân chủ Trung Hoa." }
      ]
