        { zh: "台谏官员常以“风闻奏事”对权臣形成制度制衡。", pinyin: "Táijiàn guānyuán cháng yǐ “fēngwén zòushì” duì quánchén xíngchéng zhìdù zhìhéng.", en: "Censors often petitioned on credible rumors, creating an institutional check on powerful ministers.", vi: "Quan Ngự sử thường tâu trình cả việc nghe phong văn để tạo thế chế ước quyền thần." },
        { zh: "明朝以后，御史台更名为都察院，直属最高监督系统。", pinyin: "Míngcháo yǐhòu, Yùshǐtái gēngmíng wéi Dūcháyuàn, zhíshǔ zuìgāo jiāndū xìtǒng.", en: "From the Ming dynasty onward, the Censorate was renamed the Chief Surveillance Bureau.", vi: "Từ triều Minh trở đi, Ngự sử đài đổi tên thành Đô Sát Viện thuộc hệ thống giám sát tối cao." }
