        { zh: "安徽宏村与西递的白墙黛瓦正是徽商文化的建筑结晶。", pinyin: "Ānhuī Hóngcūn yǔ Xīdì de báiqiáng dàiwǎ zhèng shì Huīshāng wénhuà de jiànzhù jiéjīng.", en: "Hongcun and Xidi's white-washed walls and black tiles crystallize Huizhou merchant architecture.", vi: "Tường trắng ngói xanh tại Hoành Thôn và Tây Đệ chính là kết tinh kiến trúc của văn hóa Huy thương." }
