      examples: [
        { zh: "“有海水处就有华人，有华商处就有潮商”道出了潮商的全球韧性。", pinyin: "“Yǒu hǎishuǐ chù jiù yǒu Huárén, yǒu Huáshāng chù jiù yǒu Cháoshāng” dàochū le Cháoshāng de quánqiú rènxìng.", en: "'Wherever sea waves reach, there are Chinese; wherever Chinese merchants trade, there are Teochews.'", vi: "Ngạn ngữ 'Đâu có nước biển là có người Hoa, đâu có Hoa thương là có Triều thương' nói lên sức sống toàn cầu của họ." },
        { zh: "在潮商办公室洽谈生意，通常先以三巡功夫茶叙情谊、立信任。", pinyin: "Zài Cháoshāng bàngōngshì qiàtán shēngyì, tōngcháng xiān yǐ sān xún gōngfuchá xù qíngyì, lì xìnrèn.", en: "In Teochew boardrooms, three rounds of Gongfu tea build rapport and trust before contract numbers.", vi: "Tại phòng làm việc của thương gia Triều Châu, ba tuần trà Công phu luôn mở đường cho chữ Tín trước khi bàn con số." },
        { zh: "清代驾“红头船”下南洋的历史培育了潮商极强的契约与抱团精神。", pinyin: "Qīngdài jià “hóngtóuchuán” xià Nányáng de lìshǐ péiyù le Cháoshāng jí qiáng de qìyuē yǔ bàotuán jīngshén.", en: "Sailing Red-Bow Junks to Southeast Asia forged fierce mutual-aid bonds among Teochew traders.", vi: "Lịch sử cưỡi thuyền đầu đỏ xuống Nam Dương đã hun đúc tinh thần khế ước và tương trợ bền chặt của Triều thương." }
      ]
