        { zh: "海商文化孕育了沿海地区开放冒险与严守契约的商业基因。", pinyin: "Hǎishāng wénhuà yùnyù le yánhǎi dìqū kāifàng màoxiǎn yǔ yánshǒu qìyuē de shāngyè jīyīn.", en: "Maritime commerce nurtured coastal genes of bold openness and strict contractual trust.", vi: "Văn hóa Hải thương ươm mầm cho vùng duyên hải bản sắc cởi mở dám dấn thân và trọng khế ước." }
