        { zh: "厚润如脂的粉青釉需要多次素烧与施釉反复入窑而成。", pinyin: "Hòurùn rú zhī de fěnqīngyòu xūyào duōcì sùshāo yǔ shīyòu fǎnfù rùyáo ér chéng.", en: "Its thick, unctuous celadon glaze required multiple bisque firings and layered glaze baths.", vi: "Lớp men phấn thanh dày mịn như ngọc mỡ đòi hỏi nhiều lần nung mộc và tráng men lặp lại." }
