        { zh: "这件国宝展现了西汉惊人的玉石微孔钻磨与冶金拉丝工艺。", pinyin: "Zhè jiàn guóbǎo zhǎnxiàn le Xī-Hàn jīngrén de yùshí wēikǒng zuānmó yǔ yějīn lāsī gōngyì.", en: "The treasure reveals astonishing Western Han jade micro-drilling and gold wire-drawing precision.", vi: "Quốc bảo này phô diễn kỹ thuật khoan mài ngọc siêu mịn và kéo sợi vàng tuyệt đỉnh của Tây Hán." }
