      mnemonic: "Đặt chữ Trà (茶) ngang hàng Kinh điển thánh hiền (经) — nâng việc uống trà hàng ngày thành Đạo (茶道).",
      context: "Lục Vũ chuẩn hóa toàn bộ hệ sinh thái: từ đất trồng đá vụn sườn nam, hái búp, 24 trà cụ (Tứ bộ khí cụ), chọn nước suối núi đến tâm thái 'Tinh hành kiệm đức'.",
      examples: [
        { zh: "唐代陆羽所撰《茶经》是世界上最早、最系统的茶叶百科全书。", pinyin: "Tángdài Lù Yǔ suǒ zhuàn 《Chájīng》 shì shìjiè shàng zuìzǎo, zuì xìtǒng de cháyè bǎikē quánshū.", en: "Tang scholar Lu Yu's Classic of Tea stands as the world's first systematic tea encyclopedia.", vi: "Bộ Trà Kinh của Lục Vũ đời Đường là bộ bách khoa toàn thư về trà sớm nhất và hệ thống nhất thế giới." },
        { zh: "陆羽在书中提出“精行俭德”四字，确立了茶道节制清和的精神内核。", pinyin: "Lù Yǔ zài shūzhōng tíchū “jīngxíng jiǎndé” sì zì, quèlì le chádào jiézhì qīnghé de jīngshén nèihé.", en: "Lu Yu anchored tea culture in refined conduct and frugal virtue, defining the heart of East Asian teaism.", vi: "Lục Vũ nêu bốn chữ 'Tinh hành kiệm đức', xác lập hạt nhân tinh thần thanh khiết tiết độ cho Trà đạo." },
        { zh: "全书考订二十四种茶器规范，影响日后东亚各国茶仪发展。", pinyin: "Quánshū kǎodìng èrshísì zhǒng cháqì guīfàn, yǐngxiǎng rìhòu Dōngyà gèguó cháyí fāzhǎn.", en: "The text codified twenty-four canonical tea utensils, shaping tea rituals across East Asia.", vi: "Tác phẩm chuẩn hóa 24 loại trà cụ, ảnh hưởng sâu sắc tới lễ nghi thưởng trà toàn khu vực Đông Á." }
      ]
