      components: "Bản cổ cầm danh tiếng nhất lịch sử gắn với tích Bá Nha gảy đàn, Chung Tử Kỳ chỉ nghe âm thanh mà thấu trọn chí hướng 'nguy nguy như Thái Sơn, dương dương như Giang Hà' ('Tri âm').",
      english: "High Mountains and Flowing Water; sublime guqin music and soulmate understanding ('Zhiyin')",
      vietnamese: "Cao sơn lưu thủy; bản cổ cầm kinh điển và điển tích tình tri âm tri kỷ sâu sắc giữa Bá Nha – Chung Tử Kỳ",
      mnemonic: "Tiếng dây tơ vang lên như núi cao sừng sững (高山) rồi tuôn chảy tựa suối nguồn bất tận (流水).",
      context: "Năm 1977, bản cổ cầm 'Lưu Thủy' (72 đoạn biến tấu của Quản Bình Hồ) được NASA khắc lên Đĩa Vàng tàu Voyager gửi vào vũ trụ làm đại diện âm nhạc nhân loại.",
      examples: [
        { zh: "伯牙鼓琴而子期听出“巍巍乎志在高山、洋洋乎志在流水”，遂成“知音”佳话。", pinyin: "Bóyá gǔqín ér Zǐqī tīngchū “wēiwēihū zhì zài gāoshān, yángyánghū zhì zài liúshuǐ”, suì chéng “zhīyīn” jiāhuà.", en: "When Ziqi heard towering mountains and flowing rivers in Boya's guqin, the ideal of 'soulmate' (zhiyin) was born.", vi: "Bá Nha gảy đàn mà Tử Kỳ nghe thấu chí ở núi cao, lòng tựa nước chảy, thành giai thoại 'Tri âm' bất hủ." },
        { zh: "《流水》古琴曲于1977年随旅行者号金唱片飞向浩瀚星际。", pinyin: "《Liúshuǐ》 gǔqínqǔ yú 1977 nián suí Lǚxíngzhěhào jīnchàngpiàn fēixiàng hàohàn xīngjì.", en: "The guqin piece Flowing Water was launched into interstellar space aboard the 1977 Voyager Golden Record.", vi: "Khúc cổ cầm Lưu Thủy năm 1977 được đưa lên Đĩa Vàng tàu Voyager bay ra không gian vũ trụ." },
        { zh: "人生得一“高山流水”般的知己，足慰平生寥落。", pinyin: "Rénshēng dé yì “gāoshān liúshuǐ” bān de zhījǐ, zú wèi píngshēng liáoluò.", en: "Finding a friend attuned like High Mountains and Flowing Water consoles a lifetime of solitude.", vi: "Đời người gặp được một tri kỷ hiểu lòng tựa khúc Cao sơn lưu thủy đủ an ủi nỗi cô độc nhân gian." }
      ]
