      examples: [
        { zh: "惊蛰时节春雷乍动，雨水渐多，正是万物苏醒、春耕大忙之始。", pinyin: "Jīngzhé shíjié chūnléi zhàdòng, yǔshuǐ jiànduō, zhèng shì wànwù sūxǐng, chūngēng dàmáng zhī shǐ.", en: "Around Awakening of Insects, spring thunder rouses dormant life and launches spring plowing.", vi: "Vào tiết Kinh Trập, sấm xuân khẽ động, mưa xuân tăng dần, mở đầu mùa vạn vật thức tỉnh và đồng áng rộn ràng." },
        { zh: "民间在惊蛰有吃梨的习俗，取“离（梨）家害虫”与润肺防燥双意。", pinyin: "Mínjiān zài Jīngzhé yǒu chī lí de xísú, qǔ “lí jiā hàichóng” yǔ rùnfèi fángzào shuāngyì.", en: "Folklore recommends eating pears at Jingzhe—playing on repelling pests and moistening spring lungs.", vi: "Dân gian tiết Kinh Trập hay ăn quả lê để xua sâu bọ ('lê' đồng âm 'ly' rời xa) và dưỡng phế phòng hanh khô." },
        { zh: "《黄帝内经》提醒惊蛰后应早睡早起，广步于庭以舒展肝气。", pinyin: "《Huángdì Nèijīng》 tíxǐng Jīngzhé hòu yīng zǎoshuì zǎoqǐ, guǎngbù yú tíng yǐ shūzhǎn gānqì.", en: "Inner Canon advises rising early after Jingzhe and strolling outdoors to let Liver qi unfold freely.", vi: "Hoàng Đế Nội Kinh nhắc sau tiết Kinh Trập nên ngủ sớm dậy sớm, dạo sân thong thả để Can khí thư thái." }
      ]
