      examples: [
        { zh: "“芒种”谐音“忙种”，北方忙于收割有芒小麦，南方忙着插秧。", pinyin: "“Mángzhòng” xiéyīn “mángzhòng”, běifāng mángyú shōugē yǒumáng xiǎomài, nánfāng mángzhe chāyāng.", en: "Pun-linked to 'busy planting,' Mangzhong finds North China harvesting bearded wheat while the South transplants rice.", vi: "'Mang chủng' đồng âm 'bận gieo trồng', miền Bắc vội gặt lúa mì có râu, miền Nam gấp rút cấy mạ lúa mùa." },
        { zh: "《红楼梦》第二十七回详尽描绘了江南芒种节饯别花神的习俗。", pinyin: "《Hónglóumèng》 dì-èrshíqī huí xiángjìn miáohuì le Jiāngnán Mángzhòng jié jiànbié huāshén de xísú.", en: "Chapter 27 of Dream of the Red Chamber vividly portrays the Mangzhong rite bidding farewell to the Flower Spirits.", vi: "Hồi 27 Hồng Lâu Mộng khắc họa tỉ mỉ phong tục tiễn Hoa Thần vào ngày tiết Mang Chủng ở Giang Nam." },
        { zh: "芒种进入闷热多雨期，饮食宜清淡少油并注重午间小憩养心。", pinyin: "Mángzhòng jìnrù mēnrè duōyǔqī, yǐnshí yí qīngdàn shǎoyóu bìng zhùzhòng wǔjiān xiǎoqì yǎngxīn.", en: "As muggy rains arrive at Mangzhong, TCM favors light meals and midday naps to protect Heart qi.", vi: "Từ Mang Chủng bước vào mùa oi nồng mưa rào, nên ăn thanh đạm và chợp mắt buổi trưa để dưỡng Tâm." }
      ]
