      examples: [
        { zh: "夏至是二十四节气中最早被天文测影确立的节令之一。", pinyin: "Xiàzhì shì èrshísì jiéqì zhōng zuìzǎo bèi tiānwén cèyǐng quèlì de jiélìng zhī yī.", en: "The Summer Solstice was among the very first solar terms fixed by ancient gnomon shadow readings.", vi: "Hạ Chí là một trong những tiết khí sớm nhất được cổ nhân xác lập bằng phương pháp đo bóng mặt trời." },
        { zh: "俗话说“冬至饺子夏至面”，北方夏至吃过水凉面以顺应新麦登场。", pinyin: "Súhuàshuō “Dōngzhì jiǎozi Xiàzhì miàn”, běifāng Xiàzhì chī guòshuǐ liángmiàn yǐ shùnyìng xīnmài dēngchǎng.", en: "'Dumplings at Winter Solstice, noodles at Summer Solstice' honors newly harvested wheat in cooling dishes.", vi: "Tục ngữ có câu 'Đông chí bánh chẻo, Hạ chí mì', người phương Bắc ăn mì nguội ngày Hạ chí mừng vụ lúa mì mới." },
        { zh: "《周易》云夏至“阳极生阴”，此时重在养阴清心而非大汗淋漓。", pinyin: "《Zhōuyì》 yún Xiàzhì “yángjí shēng yīn”, cǐshí zhòngzài yǎngyīn qīngxīn érfēi dàhàn línlí.", en: "As Yijing teaches 'when Yang peaks, Yin stirs,' Xiazhi preserves Yin fluids rather than over-sweating.", vi: "Kinh Dịch luận Hạ chí là lúc 'Dương cực sinh Âm', dưỡng sinh chú trọng bảo toàn âm dịch hơn là ra mồ hôi quá độ." }
      ]
