      english: "Autumn Equinox ('Qiufen'); 16th Solar Term of harvest and cooling balance",
      vietnamese: "Thu Phân; tiết khí giữa thu (~23/9) khi ngày đêm lại bằng nhau, chuyển từ nóng ẩm sang thu khô mát",
      mnemonic: "Mùa gặt lửa vàng (禾+火 = 秋) đứng đúng điểm chia đôi (分) ranh giới nhiệt độ chuyển từ nóng sang lạnh.",
      context: "Từ Thu phân bước vào trọng tâm dưỡng Phế phòng thu táo (tính thu chủ 'Thu liễm' — thu giữ tinh khí vào trong thay vì bung tán như mùa hè).",
      examples: [
        { zh: "秋分与春分同为昼夜平分点，此后北半球夜渐长、暑热彻底消退。", pinyin: "Qiūfēn yǔ Chūnfēn tóngwéi zhòuyè píngfēndiǎn, cǐhòu běnbànqiú yè jiàncháng, shǔrè chèdǐ xiāotuì.", en: "Like Chunfen, the Autumn Equinox balances light and dark before nights lengthen and summer heat recedes.", vi: "Thu Phân cùng Xuân Phân là hai điểm chia đều ngày đêm, sau đó đêm dài dần và cái nóng mùa hè lùi hẳn." },
        { zh: "古时礼制于春分祭日、秋分祭月，后衍化为中秋赏月盛俗。", pinyin: "Gǔshí lǐzhì yú Chūnfēn jìrì, Qiūfēn jìyuè, hòu yǎnhuà wéi Zhōngqiū shǎngyuè shèngsú.", en: "Imperial rites offered sacrifices to the sun at Chunfen and the moon at Qiufen, later evolving into Mid-Autumn rites.", vi: "Lễ chế xưa tế mặt trời vào Xuân phân, tế mặt trăng vào Thu phân, về sau hòa thành tục thưởng trăng Trung thu." },
        { zh: "秋分养生重在“润燥收神”，多食芝麻、百合、秋梨以护肺阴。", pinyin: "Qiūfēn yǎngshēng zhòngzài “rùnzào shōushén”, duōshí zhīma, bǎihé, qiūlí yǐ hù fèiyīn.", en: "Qiufen wellness moistens dryness and gathers spirit through sesame, lily bulb, and autumn pears.", vi: "Dưỡng sinh tiết Thu phân trọng 'nhuận táo thu thần', dùng vừng, bách hợp, lê thu để bảo hộ phế âm." }
      ]
