      english: "End of Heat ('Chushu'); 14th Solar Term signaling summer heat's retreat",
      vietnamese: "Xử Thử; tiết khí thứ 14 (~23/8) đánh dấu cái nóng oi bức mùa hè chính thức thu mình rút lui",
      mnemonic: "Cái nắng thiêu đốt (暑) nay tìm chỗ dừng bước ẩn mình (处), nhường chỗ cho gió thu se mát.",
      context: "Câu tục ngữ rất hay: 'Ly thu bất thị thu, Xử thử phương biến lương' — Lập thu chưa thực sự mát, phải tới Xử thử khí trời mới dịu hẳn và dễ gặp hiện tượng 'Thu lão hổ' trưa nóng đêm lạnh.",
      examples: [
        { zh: "“处暑”意为炎暑至此止步退场，“处”在此读作 chǔ（止息）。", pinyin: "“Chǔshǔ” yìwéi yánshǔ zhìcǐ zhǐbù tuìchǎng, “chǔ” zàicǐ dúzuò chǔ (zhǐxī).", en: "Chushu means scorching heat comes to a halt here, with 'chu' in the classical sense of pausing.", vi: "'Xử thử' mang nghĩa nắng nóng đến đây thì dừng bước lui về, chữ 'xử' dùng theo nghĩa cổ là nghỉ/ngưng lại." },
        { zh: "谚语“立秋不是秋，处暑见凉爽”总结了昼夜温差加大的气候规律。", pinyin: "Yànyǔ “Lìqiū bú shì qiū, Chǔshǔ jiàn liángshuǎng” zǒngjié le zhòuyè wēnchā jiādà de qìhòu guīlǜ.", en: "'Beginning of Autumn is not yet cool; Chushu brings crisp air' summarizes rising day-night thermal contrast.", vi: "Ngạn ngữ 'Lập thu bất thị thu, Xử thử kiến lương sảng' đúc kết quy luật biên độ nhiệt ngày đêm giãn rộng." },
        { zh: "老北京习惯在处暑吃鸭肉，取其滋阴润燥、温和清补之功。", pinyin: "Lǎo Běijīng xíguàn zài Chǔshǔ chī yāròu, qǔ qí zīyīn rùnzào, wēnhé qīngbǔ zhī gōng.", en: "Beijing tradition eats roast or stewed duck at Chushu for its cooling, yin-nourishing balance.", vi: "Người Bắc Kinh xưa chuộng ăn thịt vịt dịp Xử thử để tư âm nhuận táo, thanh bổ dịu mát sau mùa hè." }
      ]
