      english: "Chu Nom ('Zinan'); historical demotic Vietnamese script forged via Six-Script logic",
      vietnamese: "Chữ Nôm (Tự Nam); văn tự cổ do người Việt sáng tạo dựa trên nguyên lý Lục thư chữ Hán để ghi tiếng Việt",
      mnemonic: "Chữ viết (字) có thêm bộ Khẩu (口) đọc giọng phương Nam (南) — biểu tượng sáng tạo độc lập văn hiến Đại Việt.",
