        { zh: "诸如将“天”与“上”上下相叠表示越南语“Trời（天/上）”，极富想象力。", pinyin: "Zhūrú jiāng “tiān” yǔ “shàng” shàngxià xiāngdié biǎoshì Yuènányǔ “Trời”, jí fù xiǎngxiànglì.", en: "Stacking 'Heaven' atop 'Upper' to invent the graph for native 'Trời' displays vivid ingenuity.", vi: "Cách ghép chồng chữ 'Thiên' lên chữ 'Thượng' để tạo ra chữ 'Trời' thể hiện sức sáng tạo văn tự phi thường." },
        { zh: "阮廌《国音诗集》与阮攸《金云翘传》皆以字喃攀上越南文学巅峰。", pinyin: "Ruǎn Zhì 《Guóyīn Shījí》 yǔ Ruǎn Yōu 《Jīnyúnqiáozhuàn》 jiē yǐ Zìnán pānshàng Yuènán wénxué diānfēng.", en: "Nguyen Trai's National Language Poems and Nguyen Du's Tale of Kieu raised Chu Nom to literary summits.", vi: "Quốc Âm Thi Tập của Nguyễn Trãi và Truyện Kiều của Nguyễn Du đã đưa chữ Nôm lên đỉnh cao văn học dân tộc." }
