      vietnamese: "Mộng Âm Dương / Mão Tủn; khớp nối gỗ âm–dương giúp Tử Cấm Thành, Chùa Một Cột, Văn Miếu đứng vững trước động đất",
      mnemonic: "Đầu gỗ nhô ra (木+隼 = 榫) khớp vừa khít vào hốc âm mở sẵn (卯) mà không cần một chiếc đinh sắt.",
